// PORT-COMPLETE: g_missile.c 1/9
//! FAITHFUL port of `oracle/codemp/game/g_missile.c`.
//!
//! Originally generated by `tools/closure-prototype/fnskel.py` from the
//! fnsweep manifest, then filled by the jampgame mega-pass. Functions reach
//! file-scope game state (`level`, `g_entities`, cvars
//! `d_projectileGhoul2Collision`/`g_g2TraceLod`) and engine traps
//! (`trap_LinkEntity`/`trap_Trace`/`trap_G2Trace`) through the threaded
//! `GameContext`/`GameWorld` handle; fn-pointer fields (`think`) are set via
//! the `EntThink` enum rather than a bare fn pointer.
#![allow(non_snake_case, unused, clippy::all)]

use crate::g_utils::{G_EffectIndex, G_PlayEffectID, G_TempEntity};
use crate::prelude::*;
use crate::trap;

// Seam helpers (local to this file): `gentity_t*` stored fields
// (`parent`/`target_ent`/`activator`/`hook`) are `Option<EntityId>`; these
// resolve an id back to the live pointer needed at raw-pointer call sites
// (`G_RadiusDamage`, `G_Damage`, …) and build the id at assignment sites.
#[inline]
unsafe fn ent_resolve(ctx: GameContext<'_>, id: EntityId) -> *mut gentity_t {
    unsafe { &mut (*ctx.world).g_entities[id.index()] as *mut gentity_t }
}
#[inline]
unsafe fn ent_resolve_opt(ctx: GameContext<'_>, id: Option<EntityId>) -> *mut gentity_t {
    match id {
        Some(i) => unsafe { ent_resolve(ctx, i) },
        None => core::ptr::null_mut(),
    }
}
#[inline]
unsafe fn ent_base(ctx: GameContext<'_>) -> *const gentity_t {
    unsafe { (*ctx.world).g_entities.as_ptr() }
}

use mp_bg::public::entity_event::entity_event_t::EV_SABER_BLOCK;
use mp_bg::weapons::weapon_t::{WP_BLASTER, WP_BOWCASTER, WP_BRYAR_PISTOL};

/// Raven `G_ReflectMissile`.
///
/// Reflect the missile roughly back at it's owner.
/// Source: `oracle/codemp/game/g_missile.c:24-89`
pub fn G_ReflectMissile(ctx: GameContext<'_>, ent: EntityId, missile: EntityId, forward: vec3_t) {
    let mut bounce_dir: vec3_t = [0.0; 3];
    let mut isowner = 0;

    // Find the owner. `owner` is only null-tested below (never dereferenced) and
    // is always a live entity, so the test stays vacuously true, as in Raven.
    let mut owner: *mut gentity_t = ctx.entity_mut(ent);
    let ent_owner_num = ctx.entity(ent).r.ownerNum;
    if ent_owner_num != 0 {
        owner = ctx.entity_mut(EntityId(ent_owner_num as u32));
    }

    // Check if original owner is bouncing the missile
    if ctx.entity(missile).r.ownerNum == ctx.entity(ent).s.number {
        isowner = 1;
    }

    // Save the original speed
    let mut speed = crate::q_math::VectorNormalize(&mut ctx.entity_mut(missile).s.pos.trDelta);

    let missile_weapon = ctx.entity(missile).s.weapon;

    // Determine bounce direction
    if !owner.is_null()
        && missile_weapon != WP_SABER
        && missile_weapon != G2_MODEL_PART
        && isowner == 0
    {
        // Bounce back at them if you can
        let mut missile_to_owner: vec3_t = [0.0; 3];
        let missile_owner_num = ctx.entity(missile).r.ownerNum;
        let missile_owner_origin = ctx
            .entity(EntityId(missile_owner_num as u32))
            .r
            .currentOrigin;
        let missile_origin = ctx.entity(missile).r.currentOrigin;
        crate::q_math::_VectorSubtract(missile_owner_origin, missile_origin, &mut missile_to_owner);
        crate::q_math::VectorNormalize(&mut missile_to_owner);
        bounce_dir = missile_to_owner;
    } else if isowner != 0 {
        // Push the missile away from owner with boost — up the velocity.
        let mut missile_dir: vec3_t = [0.0; 3];
        speed *= 1.5;
        let missile_origin = ctx.entity(missile).r.currentOrigin;
        let ent_origin = ctx.entity(ent).r.currentOrigin;
        crate::q_math::_VectorSubtract(missile_origin, ent_origin, &mut missile_dir);
        crate::q_math::_VectorCopy(ctx.entity(missile).s.pos.trDelta, &mut bounce_dir);
        let dot = crate::q_math::_DotProduct(forward, missile_dir);
        crate::q_math::_VectorScale(bounce_dir, dot, &mut bounce_dir);
        crate::q_math::VectorNormalize(&mut bounce_dir);
    } else {
        // Default deflection
        let mut missile_dir: vec3_t = [0.0; 3];
        let ent_origin = ctx.entity(ent).r.currentOrigin;
        let missile_origin = ctx.entity(missile).r.currentOrigin;
        crate::q_math::_VectorSubtract(ent_origin, missile_origin, &mut missile_dir);
        crate::q_math::_VectorCopy(ctx.entity(missile).s.pos.trDelta, &mut bounce_dir);
        let dot = crate::q_math::_DotProduct(forward, missile_dir);
        crate::q_math::_VectorScale(bounce_dir, dot, &mut bounce_dir);
        crate::q_math::VectorNormalize(&mut bounce_dir);
    }

    // Add randomness
    for i in 0..3 {
        bounce_dir[i] += crate::w_saber::RandFloat(ctx, -0.2, 0.2);
    }

    crate::q_math::VectorNormalize(&mut bounce_dir);
    crate::q_math::_VectorScale(
        bounce_dir,
        speed,
        &mut ctx.entity_mut(missile).s.pos.trDelta,
    );
    ctx.entity_mut(missile).s.pos.trTime = ctx.world().level.time;
    let missile_origin = ctx.entity(missile).r.currentOrigin;
    crate::q_math::_VectorCopy(missile_origin, &mut ctx.entity_mut(missile).s.pos.trBase);

    if missile_weapon != WP_SABER && missile_weapon != G2_MODEL_PART {
        ctx.entity_mut(missile).r.ownerNum = ctx.entity(ent).s.number;
    }

    if missile_weapon == WP_ROCKET_LAUNCHER {
        ctx.entity_mut(missile).think = FnId::NONE;
        ctx.entity_mut(missile).nextthink = 0;
    }
}

/// Raven `G_DeflectMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:91-140`
pub fn G_DeflectMissile(ctx: GameContext<'_>, ent: EntityId, missile: EntityId, forward: vec3_t) {
    let mut bounce_dir: vec3_t = [0.0; 3];
    let mut missile_dir: vec3_t = [0.0; 3];
    let mut isowner = 0;

    // Check if original owner is bouncing the missile
    if ctx.entity(missile).r.ownerNum == ctx.entity(ent).s.number {
        isowner = 1;
    }

    // Save the original speed
    let speed = crate::q_math::VectorNormalize(&mut ctx.entity_mut(missile).s.pos.trDelta);

    // `client` is a raw `gentity_t*` seam field (§D5) — the gclient deref stays
    // unsafe; the entity walk is by handle.
    let ent_client = ctx.entity(ent).client;
    if !ent_client.is_null() {
        crate::q_math::AngleVectors(
            unsafe { (*(ent_client as *mut gclient_t)).ps.viewangles },
            Some(&mut missile_dir),
            None,
            None,
        );
        crate::q_math::_VectorCopy(missile_dir, &mut bounce_dir);
        let dot = crate::q_math::_DotProduct(forward, missile_dir);
        crate::q_math::_VectorScale(bounce_dir, dot, &mut bounce_dir);
        crate::q_math::VectorNormalize(&mut bounce_dir);
    } else {
        crate::q_math::_VectorCopy(forward, &mut bounce_dir);
        crate::q_math::VectorNormalize(&mut bounce_dir);
    }

    // Add randomness
    for i in 0..3 {
        bounce_dir[i] += crate::w_saber::RandFloat(ctx, -1.0, 1.0);
    }

    crate::q_math::VectorNormalize(&mut bounce_dir);
    crate::q_math::_VectorScale(
        bounce_dir,
        speed,
        &mut ctx.entity_mut(missile).s.pos.trDelta,
    );
    ctx.entity_mut(missile).s.pos.trTime = ctx.world().level.time;
    let missile_origin = ctx.entity(missile).r.currentOrigin;
    crate::q_math::_VectorCopy(missile_origin, &mut ctx.entity_mut(missile).s.pos.trBase);

    let missile_weapon = ctx.entity(missile).s.weapon;
    if missile_weapon != WP_SABER && missile_weapon != G2_MODEL_PART {
        ctx.entity_mut(missile).r.ownerNum = ctx.entity(ent).s.number;
    }

    if missile_weapon == WP_ROCKET_LAUNCHER {
        ctx.entity_mut(missile).think = FnId::NONE;
        ctx.entity_mut(missile).nextthink = 0;
    }
}

/// Raven `G_BounceMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:148-205`
pub fn G_BounceMissile(ctx: GameContext<'_>, ent: EntityId, trace: &trace_t) {
    let mut velocity: vec3_t = [0.0; 3];
    let tr = trace;

    // Reflect the velocity on the trace plane
    let (prev_time, time) = {
        let level = &ctx.world().level;
        (level.previousTime, level.time)
    };
    let hitTime = prev_time as c_float + (time - prev_time) as c_float * tr.fraction;
    crate::bg_misc::BG_EvaluateTrajectoryDelta(
        &ctx.entity(ent).s.pos,
        hitTime as c_int,
        &mut velocity,
    );
    let dot = crate::q_math::_DotProduct(velocity, tr.plane.normal);
    crate::q_math::_VectorMA(
        velocity,
        -2.0 * dot,
        tr.plane.normal,
        &mut ctx.entity_mut(ent).s.pos.trDelta,
    );

    if (ctx.entity(ent).flags & FL_BOUNCE_SHRAPNEL) != 0 {
        let trdelta = ctx.entity(ent).s.pos.trDelta;
        crate::q_math::_VectorScale(trdelta, 0.25, &mut ctx.entity_mut(ent).s.pos.trDelta);
        ctx.entity_mut(ent).s.pos.trType = TR_GRAVITY;

        // Check for stop
        if tr.plane.normal[2] > 0.7 && ctx.entity(ent).s.pos.trDelta[2] < 40.0 {
            G_SetOrigin(ctx.entity_mut(ent), tr.endpos);
            ctx.entity_mut(ent).nextthink = ctx.world().level.time + 100;
            return;
        }
    } else if (ctx.entity(ent).flags & FL_BOUNCE_HALF) != 0 {
        let trdelta = ctx.entity(ent).s.pos.trDelta;
        crate::q_math::_VectorScale(trdelta, 0.65, &mut ctx.entity_mut(ent).s.pos.trDelta);
        // Check for stop.
        // `normal[2]` (float) and `VectorLength` (float) promote to double
        // against the unsuffixed `0.2`/`40` in C; the f32-nearest 0.2 exceeds
        // double 0.2, so evaluate in f64 to keep the branch decision.
        if (tr.plane.normal[2] as f64) > 0.2
            && (crate::q_math::VectorLength(ctx.entity(ent).s.pos.trDelta) as f64) < 40.0
        {
            G_SetOrigin(ctx.entity_mut(ent), tr.endpos);
            return;
        }
    }

    // Play bounce sound
    let weapon = ctx.entity(ent).s.weapon;
    if weapon == WP_THERMAL {
        let sound_name = cstr(&format!(
            "sound/weapons/thermal/bounce{}.wav",
            ctx.world().bg_state.rng.Q_irand(1, 2)
        ));
        G_Sound(
            ctx,
            Some(ent),
            CHAN_BODY as c_int,
            G_SoundIndex(sound_name.as_ptr()),
        );
    } else if weapon == WP_SABER {
        let sound_name = cstr(&format!(
            "sound/weapons/saber/bounce{}.wav",
            ctx.world().bg_state.rng.Q_irand(1, 3)
        ));
        G_Sound(
            ctx,
            Some(ent),
            CHAN_BODY as c_int,
            G_SoundIndex(sound_name.as_ptr()),
        );
    }

    let currentOrigin = ctx.entity(ent).r.currentOrigin;
    crate::q_math::_VectorAdd(
        currentOrigin,
        tr.plane.normal,
        &mut ctx.entity_mut(ent).r.currentOrigin,
    );
    let currentOrigin = ctx.entity(ent).r.currentOrigin;
    crate::q_math::_VectorCopy(currentOrigin, &mut ctx.entity_mut(ent).s.pos.trBase);
    ctx.entity_mut(ent).s.pos.trTime = ctx.world().level.time;

    if ctx.entity(ent).bounceCount != -5 {
        ctx.entity_mut(ent).bounceCount -= 1;
    }
}

/// Raven `G_ExplodeMissile`.
///
/// Explode a missile without an impact.
/// Source: `oracle/codemp/game/g_missile.c:215-257`
pub fn G_ExplodeMissile(ctx: GameContext<'_>, ent: EntityId) {
    let mut dir: vec3_t = [0.0, 0.0, 1.0];
    let mut origin: vec3_t = [0.0; 3];

    let time = ctx.world().level.time;
    crate::bg_misc::BG_EvaluateTrajectory(&ctx.entity(ent).s.pos, time, &mut origin);
    trap::SnapVector(
        ctx.engine,
        mp_abi::game::syscalls::G_SNAPVECTOR::GSnapvectorArgs::new(&mut origin),
    );
    G_SetOrigin(ctx.entity_mut(ent), origin);

    ctx.entity_mut(ent).s.eType = ET_GENERAL as c_int;
    G_AddEvent(
        ctx.entity_mut(ent),
        EV_MISSILE_MISS as c_int,
        DirToByte(dir),
    );

    ctx.entity_mut(ent).freeAfterEvent = qtrue;
    ctx.entity_mut(ent).takedamage = qfalse;

    // Splash damage
    if ctx.entity(ent).splashDamage != 0 {
        // Check if we need to set parent for damage credit. (`s.eType` was just
        // set to ET_GENERAL above, so this ET_MISSILE test never fires —
        // faithful to Raven.)
        if ctx.entity(ent).s.eType == ET_MISSILE as c_int
            && ((ctx.entity(ent).s.eFlags & EF_JETPACK_ACTIVE) != 0)
            && (ctx.entity(ent).r.ownerNum as usize) < MAX_CLIENTS
        {
            let owner_num = ctx.entity(ent).r.ownerNum as usize;
            ctx.entity_mut(ent).parent =
                Some(unsafe { ent_id(ent_base(ctx), &ctx.world().g_entities[owner_num]) });
        }

        let parent = ctx.entity(ent).parent;
        let currentOrigin = ctx.entity(ent).r.currentOrigin;
        let splashDamage = ctx.entity(ent).splashDamage;
        let splashRadius = ctx.entity(ent).splashRadius;
        let splashMod = ctx.entity(ent).splashMethodOfDeath;
        let parent_ptr = unsafe { ent_resolve_opt(ctx, parent) };
        if G_RadiusDamage(
            ctx,
            currentOrigin,
            ctx.entity_id_of(parent_ptr),
            splashDamage as f32,
            splashRadius as f32,
            ctx.entity_id_of(ctx.entity_mut(ent)),
            ctx.entity_id_of(ctx.entity_mut(ent)),
            splashMod,
        ) != 0
        {
            if let Some(parent_id) = parent {
                let client = ctx.entity(parent_id).client;
                if !client.is_null() {
                    unsafe {
                        (*(client as *mut gclient_t)).accuracy_hits += 1;
                    }
                }
            } else if let Some(activator_id) = ctx.entity(ent).activator {
                let client = ctx.entity(activator_id).client;
                if !client.is_null() {
                    unsafe {
                        (*(client as *mut gclient_t)).accuracy_hits += 1;
                    }
                }
            }
        }
    }

    trap::LinkEntity(
        ctx.engine,
        mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ctx.entity_mut(ent)),
    );
}

/// Raven `G_RunStuckMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:259-277`
pub fn G_RunStuckMissile(ctx: GameContext<'_>, ent: EntityId) {
    if ctx.entity(ent).takedamage != 0 {
        let ground = ctx.entity(ent).s.groundEntityNum;
        if ground >= 0 && (ground as usize) < ENTITYNUM_WORLD as usize {
            let other = EntityId(ground as u32);

            let delta_moving =
                VectorCompare(crate::q_math::vec3_origin, ctx.entity(other).s.pos.trDelta) == 0
                    && ctx.entity(other).s.pos.trType != TR_STATIONARY;
            let apos_moving =
                VectorCompare(crate::q_math::vec3_origin, ctx.entity(other).s.apos.trDelta) == 0
                    && ctx.entity(other).s.apos.trType != TR_STATIONARY;

            if delta_moving || apos_moving {
                // Thing I stuck to is moving or rotating now, kill me
                G_Damage(
                    ctx,
                    ctx.entity_id_of(ctx.entity_mut(ent)),
                    ctx.entity_id_of(ctx.entity_mut(other)),
                    ctx.entity_id_of(ctx.entity_mut(other)),
                    None,
                    crate::q_math::vec3_origin,
                    99999,
                    0,
                    MOD_CRUSH as c_int,
                );
                return;
            }
        }
    }
    // Check think function
    G_RunThink(ctx, ent);
}

/// Raven `G_BounceProjectile`.
///
/// Source: `oracle/codemp/game/g_missile.c:284-294`
pub fn G_BounceProjectile(start: vec3_t, impact: vec3_t, dir: vec3_t, endout: &mut [f32; 3]) {
    let mut v: vec3_t = [0.0; 3];
    let mut newv: vec3_t = [0.0; 3];

    crate::q_math::_VectorSubtract(impact, start, &mut v);
    let dot = crate::q_math::_DotProduct(v, dir);
    crate::q_math::_VectorMA(v, -2.0 * dot, dir, &mut newv);

    crate::q_math::VectorNormalize(&mut newv);
    crate::q_math::_VectorMA(impact, 8192.0, newv, endout);
}

/// Raven `CreateMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:298-329`
pub fn CreateMissile(
    ctx: GameContext<'_>,
    org: vec3_t,
    dir: vec3_t,
    vel: f32,
    life: c_int,
    owner: EntityId,
    altFire: qboolean,
) -> *mut gentity_t {
    // Return type stays `*mut gentity_t` (Stage 1 converts params only; the many
    // external callers consume the raw pointer). `missile_ptr` is the freshly
    // spawned slot; its handle drives the accessor body.
    let missile_ptr = G_Spawn(ctx);
    let missile = ctx.entity_id_of(missile_ptr).unwrap();

    ctx.entity_mut(missile).nextthink = ctx.world().level.time + life;
    ctx.entity_mut(missile).think = Some(EntThink::G_FreeEntity).into();
    ctx.entity_mut(missile).s.eType = ET_MISSILE as c_int;
    ctx.entity_mut(missile).r.svFlags = SVF_USE_CURRENT_ORIGIN;
    ctx.entity_mut(missile).parent = Some(owner);
    ctx.entity_mut(missile).r.ownerNum = ctx.entity(owner).s.number;

    if altFire != 0 {
        ctx.entity_mut(missile).s.eFlags |= EF_ALT_FIRING;
    }

    ctx.entity_mut(missile).s.pos.trType = TR_LINEAR;
    ctx.entity_mut(missile).s.pos.trTime = ctx.world().level.time;
    ctx.entity_mut(missile).target_ent = None;

    let mut snapped_org = org;
    trap::SnapVector(
        ctx.engine,
        mp_abi::game::syscalls::G_SNAPVECTOR::GSnapvectorArgs::new(&mut snapped_org),
    );
    crate::q_math::_VectorCopy(snapped_org, &mut ctx.entity_mut(missile).s.pos.trBase);
    crate::q_math::_VectorScale(dir, vel, &mut ctx.entity_mut(missile).s.pos.trDelta);
    crate::q_math::_VectorCopy(snapped_org, &mut ctx.entity_mut(missile).r.currentOrigin);
    trap::SnapVector(
        ctx.engine,
        mp_abi::game::syscalls::G_SNAPVECTOR::GSnapvectorArgs::new(
            &mut ctx.entity_mut(missile).s.pos.trDelta,
        ),
    );

    missile_ptr
}

/// Raven `G_MissileBounceEffect`.
///
/// Source: `oracle/codemp/game/g_missile.c:331-354`
pub fn G_MissileBounceEffect(ctx: GameContext<'_>, ent: EntityId, org: vec3_t, dir: vec3_t) {
    //FIXME: have an EV_BOUNCE_MISSILE event that checks the s.weapon and does the appropriate effect
    match ctx.entity(ent).s.weapon {
        WP_BOWCASTER => {
            let fx = G_EffectIndex(c"bowcaster/deflect".as_ptr());
            let currentOrigin = ctx.entity(ent).r.currentOrigin;
            G_PlayEffectID(fx, currentOrigin, dir);
        }
        WP_BLASTER | WP_BRYAR_PISTOL => {
            let fx = G_EffectIndex(c"blaster/deflect".as_ptr());
            let currentOrigin = ctx.entity(ent).r.currentOrigin;
            G_PlayEffectID(fx, currentOrigin, dir);
        }
        _ => {
            let te = ctx
                .entity_id_of(G_TempEntity(ctx, org, EV_SABER_BLOCK as c_int))
                .unwrap();
            let te = ctx.entity_mut(te);
            te.s.origin = org;
            te.s.angles = dir;
            te.s.eventParm = 0;
            te.s.weapon = 0; //saberNum
            te.s.legsAnim = 0; //bladeNum
        }
    }
}

/// Raven `G_MissileImpact`.
///
/// Source: `oracle/codemp/game/g_missile.c:362-801`
pub fn G_MissileImpact(ctx: GameContext<'_>, ent: EntityId, trace: &mut trace_t) {
    // Stage-1 seam: params are handles. This impact routine is saturated with
    // raw `gclient_t`/vehicle seam derefs and calls into still-raw fns, so the
    // verified body stays pointer-based behind the accessor bridge (rule 6):
    // `ent`/`trace` are re-derived to raw pointers here and sibling shard calls
    // are bridged to handles. Full accessor conversion is deferred (see report).
    unsafe {
        let ent_id = ent;
        let ent: *mut gentity_t = ctx.entity_mut(ent_id);
        let trace: *mut trace_t = trace;
        let tr = &mut *trace;
        let mut other = &mut (*ctx.world).g_entities[tr.entityNum as usize];
        let mut hitClient = qfalse;
        let mut isKnockedSaber = qfalse;

        // Check for bounce
        if (*other).takedamage == 0
            && ((*ent).bounceCount > 0 || (*ent).bounceCount == -5)
            && (((*ent).flags & (FL_BOUNCE | FL_BOUNCE_HALF)) != 0)
        {
            G_BounceMissile(ctx, ent_id, &*trace);
            G_AddEvent(&mut *(ent), EV_GRENADE_BOUNCE as c_int, 0);
            return;
        } else if (*ent).neverFree != 0
            && (*ent).s.weapon == WP_SABER
            && (((*ent).flags & FL_BOUNCE_HALF) != 0)
        {
            // This is a knocked-away saber
            if (*ent).bounceCount > 0 || (*ent).bounceCount == -5 {
                G_BounceMissile(ctx, ent_id, &*trace);
                G_AddEvent(&mut *(ent), EV_GRENADE_BOUNCE as c_int, 0);
                return;
            }
            isKnockedSaber = qtrue;
        }

        // Bounce shrapnel and force field handling
        if ((*other).takedamage == 0
            && ((*ent).bounceCount > 0 || (*ent).bounceCount == -5)
            && (((*ent).flags & FL_BOUNCE_SHRAPNEL) != 0))
            || (((tr.surfaceFlags & SURF_FORCEFIELD) != 0)
                && (*ent).splashDamage == 0
                && (*ent).splashRadius == 0
                && ((*ent).bounceCount > 0 || (*ent).bounceCount == -5))
        {
            G_BounceMissile(ctx, ent_id, &*trace);
            if (*ent).bounceCount < 1 {
                (*ent).flags &= !FL_BOUNCE_SHRAPNEL;
            }
            return;
        }

        // Saber block checks
        if (((*other).r.contents & CONTENTS_LIGHTSABER) != 0) && isKnockedSaber == 0 {
            let otherOwner = &mut (*ctx.world).g_entities[(*other).r.ownerNum as usize];
            if (*otherOwner).takedamage != 0
                && !(*otherOwner).client.is_null()
                && (*((*otherOwner).client as *mut gclient_t))
                    .ps
                    .duelInProgress
                    != 0
                && (*((*otherOwner).client as *mut gclient_t)).ps.duelIndex != (*ent).r.ownerNum
            {
                // Jump to killProj label
                let mut dir: vec3_t = [0.0, 0.0, 1.0];
                if (*other).takedamage != 0 && !(*other).client.is_null() && isKnockedSaber == 0 {
                    G_AddEvent(
                        &mut *(ent),
                        EV_MISSILE_HIT as c_int,
                        DirToByte(tr.plane.normal),
                    );
                    (*ent).s.otherEntityNum = (*other).s.number;
                } else if (tr.surfaceFlags & SURF_METALSTEPS) != 0 {
                    G_AddEvent(
                        &mut *(ent),
                        EV_MISSILE_MISS_METAL as c_int,
                        DirToByte(tr.plane.normal),
                    );
                } else if (*ent).s.weapon != G2_MODEL_PART && isKnockedSaber == 0 {
                    G_AddEvent(
                        &mut *(ent),
                        EV_MISSILE_MISS as c_int,
                        DirToByte(tr.plane.normal),
                    );
                }
                if isKnockedSaber == 0 {
                    (*ent).freeAfterEvent = qtrue;
                    (*ent).s.eType = ET_GENERAL as c_int;
                }
                tr.endpos = crate::g_weapon::SnapVectorTowards(tr.endpos, (*ent).s.pos.trBase);
                G_SetOrigin(&mut *(ent), tr.endpos);
                (*ent).takedamage = qfalse;
                if (*ent).splashDamage != 0 {
                    if G_RadiusDamage(
                        ctx,
                        tr.endpos,
                        ctx.entity_id_of(ent_resolve_opt(ctx, (*ent).parent)),
                        (*ent).splashDamage as f32,
                        (*ent).splashRadius as f32,
                        ctx.entity_id_of(other),
                        ctx.entity_id_of(ent),
                        (*ent).splashMethodOfDeath,
                    ) != 0
                    {
                        if hitClient == 0
                            && !(*ctx.world).g_entities[(*ent).r.ownerNum as usize]
                                .client
                                .is_null()
                        {
                            (*((*ctx.world).g_entities[(*ent).r.ownerNum as usize].client
                                as *mut gclient_t))
                                .accuracy_hits += 1;
                        }
                    }
                }
                if (*ent).s.weapon == G2_MODEL_PART {
                    (*ent).freeAfterEvent = qfalse;
                }
                trap::LinkEntity(
                    ctx.engine,
                    mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
                );
                return;
            }
        } else if isKnockedSaber == 0 {
            if (*other).takedamage != 0
                && !(*other).client.is_null()
                && (*((*other).client as *mut gclient_t)).ps.duelInProgress != 0
                && (*((*other).client as *mut gclient_t)).ps.duelIndex != (*ent).r.ownerNum
            {
                // Jump to killProj label
                let mut dir: vec3_t = [0.0, 0.0, 1.0];
                if (*other).takedamage != 0 && !(*other).client.is_null() && isKnockedSaber == 0 {
                    G_AddEvent(
                        &mut *(ent),
                        EV_MISSILE_HIT as c_int,
                        DirToByte(tr.plane.normal),
                    );
                    (*ent).s.otherEntityNum = (*other).s.number;
                } else if (tr.surfaceFlags & SURF_METALSTEPS) != 0 {
                    G_AddEvent(
                        &mut *(ent),
                        EV_MISSILE_MISS_METAL as c_int,
                        DirToByte(tr.plane.normal),
                    );
                } else if (*ent).s.weapon != G2_MODEL_PART && isKnockedSaber == 0 {
                    G_AddEvent(
                        &mut *(ent),
                        EV_MISSILE_MISS as c_int,
                        DirToByte(tr.plane.normal),
                    );
                }
                if isKnockedSaber == 0 {
                    (*ent).freeAfterEvent = qtrue;
                    (*ent).s.eType = ET_GENERAL as c_int;
                }
                tr.endpos = crate::g_weapon::SnapVectorTowards(tr.endpos, (*ent).s.pos.trBase);
                G_SetOrigin(&mut *(ent), tr.endpos);
                (*ent).takedamage = qfalse;
                if (*ent).splashDamage != 0 {
                    if G_RadiusDamage(
                        ctx,
                        tr.endpos,
                        ctx.entity_id_of(ent_resolve_opt(ctx, (*ent).parent)),
                        (*ent).splashDamage as f32,
                        (*ent).splashRadius as f32,
                        ctx.entity_id_of(other),
                        ctx.entity_id_of(ent),
                        (*ent).splashMethodOfDeath,
                    ) != 0
                    {
                        if hitClient == 0
                            && !(*ctx.world).g_entities[(*ent).r.ownerNum as usize]
                                .client
                                .is_null()
                        {
                            (*((*ctx.world).g_entities[(*ent).r.ownerNum as usize].client
                                as *mut gclient_t))
                                .accuracy_hits += 1;
                        }
                    }
                }
                if (*ent).s.weapon == G2_MODEL_PART {
                    (*ent).freeAfterEvent = qfalse;
                }
                trap::LinkEntity(
                    ctx.engine,
                    mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
                );
                return;
            }
        }

        // Heavy weapon deflection check
        if ((*other).flags & FL_DMG_BY_HEAVY_WEAP_ONLY) != 0 {
            if (*ent).methodOfDeath != MOD_REPEATER_ALT as c_int
                && (*ent).methodOfDeath != MOD_ROCKET as c_int
                && (*ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
                && (*ent).methodOfDeath != MOD_ROCKET_HOMING as c_int
                && (*ent).methodOfDeath != MOD_THERMAL as c_int
                && (*ent).methodOfDeath != MOD_THERMAL_SPLASH as c_int
                && (*ent).methodOfDeath != MOD_TRIP_MINE_SPLASH as c_int
                && (*ent).methodOfDeath != MOD_TIMED_MINE_SPLASH as c_int
                && (*ent).methodOfDeath != MOD_DET_PACK_SPLASH as c_int
                && (*ent).methodOfDeath != MOD_VEHICLE as c_int
                && (*ent).methodOfDeath != MOD_CONC as c_int
                && (*ent).methodOfDeath != MOD_CONC_ALT as c_int
                && (*ent).methodOfDeath != MOD_SABER as c_int
                && (*ent).methodOfDeath != MOD_TURBLAST as c_int
                && (*ent).methodOfDeath != MOD_TARGET_LASER as c_int
            {
                let mut fwd: vec3_t = [0.0; 3];
                if !trace.is_null() {
                    crate::q_math::_VectorCopy(tr.plane.normal, &mut fwd);
                } else {
                    crate::q_math::AngleVectors(
                        (*other).r.currentAngles,
                        Some(&mut fwd),
                        None,
                        None,
                    );
                }
                G_DeflectMissile(ctx, ctx.entity_id_of(other).unwrap(), ent_id, fwd);
                G_MissileBounceEffect(ctx, ent_id, (*ent).r.currentOrigin, fwd);
                return;
            }
        }

        // Shielded entity deflection
        if (((*other).flags & FL_SHIELDED) != 0)
            && (*ent).s.weapon != WP_ROCKET_LAUNCHER
            && (*ent).s.weapon != WP_THERMAL
            && (*ent).s.weapon != WP_TRIP_MINE
            && (*ent).s.weapon != WP_DET_PACK
            && (*ent).s.weapon != WP_DEMP2
            && (*ent).s.weapon != WP_EMPLACED_GUN
            && (*ent).methodOfDeath != MOD_REPEATER_ALT as c_int
            && (*ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
            && (*ent).methodOfDeath != MOD_TURBLAST as c_int
            && (*ent).methodOfDeath != MOD_TARGET_LASER as c_int
            && (*ent).methodOfDeath != MOD_VEHICLE as c_int
            && (*ent).methodOfDeath != MOD_CONC as c_int
            && (*ent).methodOfDeath != MOD_CONC_ALT as c_int
            && ((*ent).dflags & DAMAGE_HEAVY_WEAP_CLASS) == 0
        {
            let mut fwd: vec3_t = [0.0; 3];
            if !(*other).client.is_null() {
                crate::q_math::AngleVectors(
                    (*((*other).client as *mut gclient_t)).ps.viewangles,
                    Some(&mut fwd),
                    None,
                    None,
                );
            } else {
                crate::q_math::AngleVectors((*other).r.currentAngles, Some(&mut fwd), None, None);
            }
            G_DeflectMissile(ctx, ctx.entity_id_of(other).unwrap(), ent_id, fwd);
            G_MissileBounceEffect(ctx, ent_id, (*ent).r.currentOrigin, fwd);
            return;
        }

        // Saber block handling
        if (*other).takedamage != 0
            && !(*other).client.is_null()
            && (*ent).s.weapon != WP_ROCKET_LAUNCHER
            && (*ent).s.weapon != WP_THERMAL
            && (*ent).s.weapon != WP_TRIP_MINE
            && (*ent).s.weapon != WP_DET_PACK
            && (*ent).s.weapon != WP_DEMP2
            && (*ent).methodOfDeath != MOD_REPEATER_ALT as c_int
            && (*ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
            && (*ent).methodOfDeath != MOD_CONC as c_int
            && (*ent).methodOfDeath != MOD_CONC_ALT as c_int
            && (*((*other).client as *mut gclient_t)).ps.saberBlockTime < (*ctx.world).level.time
            && isKnockedSaber == 0
            && WP_SaberCanBlock(
                ctx,
                ctx.entity_id_of(other),
                (*ent).r.currentOrigin,
                0,
                0,
                qtrue,
                0,
            ) != 0
        {
            let mut fwd: vec3_t = [0.0; 3];
            let otherDefLevel = (*((*other).client as *mut gclient_t)).ps.fd.forcePowerLevel
                [FP_SABER_DEFENSE as usize];

            let te = G_TempEntity(ctx, (*ent).r.currentOrigin, EV_SABER_BLOCK as c_int);
            crate::q_math::_VectorCopy((*ent).r.currentOrigin, &mut (*te).s.origin);
            crate::q_math::_VectorCopy(tr.plane.normal, &mut (*te).s.angles);
            (*te).s.eventParm = 0;
            (*te).s.weapon = 0;
            (*te).s.legsAnim = 0;

            let mut adjusted_def_level = otherDefLevel;
            if (*((*other).client as *mut gclient_t)).ps.velocity[2] > 0.0
                || (*((*other).client as *mut gclient_t)).pers.cmd.forwardmove < 0
            {
                adjusted_def_level -= 1;
                if adjusted_def_level < 0 {
                    adjusted_def_level = 0;
                }
            }

            crate::q_math::AngleVectors(
                (*((*other).client as *mut gclient_t)).ps.viewangles,
                Some(&mut fwd),
                None,
                None,
            );
            if adjusted_def_level == FORCE_LEVEL_1 as c_int {
                // Kill the projectile
            } else if adjusted_def_level == FORCE_LEVEL_2 as c_int {
                G_DeflectMissile(ctx, ctx.entity_id_of(other).unwrap(), ent_id, fwd);
            } else {
                G_ReflectMissile(ctx, ctx.entity_id_of(other).unwrap(), ent_id, fwd);
            }
            (*((*other).client as *mut gclient_t)).ps.saberBlockTime =
                (*ctx.world).level.time + (350 - (adjusted_def_level * 100));
            (*((*other).client as *mut gclient_t)).ps.saberEventFlags |= SEF_DEFLECTED;

            if adjusted_def_level == FORCE_LEVEL_3 as c_int {
                (*((*other).client as *mut gclient_t)).ps.saberBlockTime = 0;
            }

            if adjusted_def_level == FORCE_LEVEL_1 as c_int {
                // Fall through to killProj
            } else {
                return;
            }
        } else if (((*other).r.contents & CONTENTS_LIGHTSABER) != 0) && isKnockedSaber == 0 {
            let otherOwner = &mut (*ctx.world).g_entities[(*other).r.ownerNum as usize];
            if (*otherOwner).takedamage != 0
                && !(*otherOwner).client.is_null()
                && (*ent).s.weapon != WP_ROCKET_LAUNCHER
                && (*ent).s.weapon != WP_THERMAL
                && (*ent).s.weapon != WP_TRIP_MINE
                && (*ent).s.weapon != WP_DET_PACK
                && (*ent).s.weapon != WP_DEMP2
                && (*ent).methodOfDeath != MOD_REPEATER_ALT as c_int
                && (*ent).methodOfDeath != MOD_FLECHETTE_ALT_SPLASH as c_int
                && (*ent).methodOfDeath != MOD_CONC as c_int
                && (*ent).methodOfDeath != MOD_CONC_ALT as c_int
            {
                let mut fwd: vec3_t = [0.0; 3];
                // Deflect it even if we can't actually block it because it hit
                // our saber — triggers the defender's saber-block animation.
                if !(*otherOwner).client.is_null()
                    && (*((*otherOwner).client as *mut gclient_t)).ps.weaponTime <= 0
                {
                    crate::w_saber::WP_SaberBlockNonRandom(
                        &*(otherOwner as *mut gentity_t),
                        (*ent).r.currentOrigin,
                        qtrue,
                    );
                }
                let te = G_TempEntity(ctx, (*ent).r.currentOrigin, EV_SABER_BLOCK as c_int);
                crate::q_math::_VectorCopy((*ent).r.currentOrigin, &mut (*te).s.origin);
                crate::q_math::_VectorCopy(tr.plane.normal, &mut (*te).s.angles);
                (*te).s.eventParm = 0;
                (*te).s.weapon = 0;
                (*te).s.legsAnim = 0;

                let mut other_def_level = (*((*otherOwner).client as *mut gclient_t))
                    .ps
                    .fd
                    .forcePowerLevel[FP_SABER_DEFENSE as usize];
                if (*((*otherOwner).client as *mut gclient_t)).ps.velocity[2] > 0.0
                    || (*((*otherOwner).client as *mut gclient_t))
                        .pers
                        .cmd
                        .forwardmove
                        < 0
                {
                    other_def_level -= 1;
                    if other_def_level < 0 {
                        other_def_level = 0;
                    }
                }

                crate::q_math::AngleVectors(
                    (*((*otherOwner).client as *mut gclient_t)).ps.viewangles,
                    Some(&mut fwd),
                    None,
                    None,
                );

                if other_def_level == FORCE_LEVEL_1 as c_int {
                    // Kill projectile
                } else if other_def_level == FORCE_LEVEL_2 as c_int {
                    G_DeflectMissile(ctx, ctx.entity_id_of(otherOwner).unwrap(), ent_id, fwd);
                } else {
                    G_ReflectMissile(ctx, ctx.entity_id_of(otherOwner).unwrap(), ent_id, fwd);
                }
                (*((*otherOwner).client as *mut gclient_t))
                    .ps
                    .saberBlockTime = (*ctx.world).level.time + (350 - (other_def_level * 100));
                (*((*otherOwner).client as *mut gclient_t))
                    .ps
                    .saberEventFlags |= SEF_DEFLECTED;

                if other_def_level == FORCE_LEVEL_3 as c_int {
                    (*((*otherOwner).client as *mut gclient_t))
                        .ps
                        .saberBlockTime = 0;
                }

                if other_def_level == FORCE_LEVEL_1 as c_int {
                    // Fall through to killProj
                } else {
                    return;
                }
            }
        }

        // Sticky missiles
        if (*other).takedamage == 0 && (((*ent).s.eFlags & EF_MISSILE_STICK) != 0) {
            laserTrapStick(
                ctx,
                ctx.entity_id_of(ent).unwrap(),
                tr.endpos,
                tr.plane.normal,
            );
            G_AddEvent(&mut *(ent), EV_MISSILE_STICK as c_int, 0);
            return;
        }

        // Impact damage
        if (*other).takedamage != 0 && isKnockedSaber == 0 {
            if (*ent).damage != 0 {
                let mut velocity: vec3_t = [0.0; 3];
                let mut didDmg = qfalse;

                let owner_ent =
                    &mut (*ctx.world).g_entities[(*ent).r.ownerNum as usize] as *mut gentity_t;
                if LogAccuracyHit(
                    ctx,
                    ctx.entity_id_of(other).unwrap(),
                    ctx.entity_id_of(owner_ent),
                ) != 0
                {
                    (*((*ctx.world).g_entities[(*ent).r.ownerNum as usize].client
                        as *mut gclient_t))
                        .accuracy_hits += 1;
                    hitClient = qtrue;
                }

                crate::bg_misc::BG_EvaluateTrajectoryDelta(
                    &(*ent).s.pos,
                    (*ctx.world).level.time,
                    &mut velocity,
                );
                if crate::q_math::VectorLength(velocity) == 0.0 {
                    velocity[2] = 1.0;
                }

                if (*ent).s.weapon == WP_BOWCASTER
                    || (*ent).s.weapon == WP_FLECHETTE
                    || (*ent).s.weapon == WP_ROCKET_LAUNCHER
                {
                    if (*ent).s.weapon == WP_FLECHETTE && (((*ent).s.eFlags & EF_ALT_FIRING) != 0) {
                        if let Some(think_fn) = (*ent).think.get() {
                            // Call the think function
                            crate::ent_fn_enums::dispatch_think(ctx, think_fn, ent);
                        }
                    } else {
                        G_Damage(
                            ctx,
                            ctx.entity_id_of(other),
                            ctx.entity_id_of(ent),
                            EntityId::from_num((*ent).r.ownerNum),
                            Some(&mut velocity),
                            (*ent).r.currentOrigin,
                            (*ent).damage,
                            DAMAGE_HALF_ABSORB as c_int,
                            (*ent).methodOfDeath,
                        );
                        didDmg = qtrue;
                    }
                } else {
                    G_Damage(
                        ctx,
                        ctx.entity_id_of(other),
                        ctx.entity_id_of(ent),
                        EntityId::from_num((*ent).r.ownerNum),
                        Some(&mut velocity),
                        (*ent).r.currentOrigin,
                        (*ent).damage,
                        0,
                        (*ent).methodOfDeath,
                    );
                    didDmg = qtrue;
                }

                if didDmg != 0 && !(*other).client.is_null() {
                    let npc_class = (*((*other).client as *mut gclient_t)).NPC_class;
                    if npc_class == CLASS_SEEKER
                        || npc_class == CLASS_PROBE
                        || npc_class == CLASS_MOUSE
                        || npc_class == CLASS_GONK
                        || npc_class == CLASS_R2D2
                        || npc_class == CLASS_R5D2
                        || npc_class == CLASS_REMOTE
                        || npc_class == CLASS_MARK1
                        || npc_class == CLASS_MARK2
                        || npc_class == CLASS_INTERROGATOR
                        || npc_class == CLASS_ATST
                        || npc_class == CLASS_SENTRY
                    {
                        if (*((*other).client as *mut gclient_t)).ps.electrifyTime
                            < (*ctx.world).level.time + 100
                        {
                            (*((*other).client as *mut gclient_t)).ps.electrifyTime =
                                (*ctx.world).level.time + 450;
                        }
                    }
                }
            }

            if (*ent).s.weapon == WP_DEMP2 {
                if !(*other).client.is_null()
                    && (*((*other).client as *mut gclient_t)).NPC_class == CLASS_VEHICLE
                {
                    let other_vehicle = (*other).m_pVehicle as *mut Vehicle_t;
                    if !other_vehicle.is_null()
                        && !(*other_vehicle).m_pVehicleInfo.is_null()
                        && ((*(*other_vehicle).m_pVehicleInfo).r#type == VH_SPEEDER
                            || ((*(*other_vehicle).m_pVehicleInfo).r#type == VH_FIGHTER
                                && !(*ent).classname.is_null()
                                && crate::q_shared::Q_stricmp(
                                    (*ent).classname,
                                    c"vehicle_proj".as_ptr() as *const c_char,
                                ) == 0))
                        && FighterIsLanded(
                            other_vehicle,
                            &mut (*((*other).client as *mut gclient_t)).ps,
                        ) == 0
                        && (((*other).spawnflags & 2) == 0)
                    {
                        if (*((*other).client as *mut gclient_t)).ps.electrifyTime
                            > (*ctx.world).level.time
                        {
                            (*((*other).client as *mut gclient_t)).ps.electrifyTime +=
                                (*ctx.world).bg_state.rng.Q_irand(200, 500);
                            if (*((*other).client as *mut gclient_t)).ps.electrifyTime
                                > (*ctx.world).level.time + 4000
                            {
                                (*((*other).client as *mut gclient_t)).ps.electrifyTime =
                                    (*ctx.world).level.time + 4000;
                            }
                        } else {
                            (*((*other).client as *mut gclient_t)).ps.electrifyTime =
                                (*ctx.world).level.time
                                    + (*ctx.world).bg_state.rng.Q_irand(200, 500);
                        }
                    }
                } else if !(*other).client.is_null()
                    && (*((*other).client as *mut gclient_t)).ps.powerups[PW_CLOAKED as usize] != 0
                {
                    Jedi_Decloak(ctx, ctx.entity_id_of(other));
                    if (*ent).methodOfDeath == MOD_DEMP2_ALT as c_int {
                        (*((*other).client as *mut gclient_t)).cloakToggleTime = Q3_INFINITE;
                    } else {
                        (*((*other).client as *mut gclient_t)).cloakToggleTime =
                            (*ctx.world).level.time
                                + (*ctx.world).bg_state.rng.Q_irand(3000, 10000);
                    }
                }
            }
        }

        // killProj label - generate impact event
        let mut dir: vec3_t = [0.0, 0.0, 1.0];
        if (*other).takedamage != 0 && !(*other).client.is_null() && isKnockedSaber == 0 {
            G_AddEvent(
                &mut *(ent),
                EV_MISSILE_HIT as c_int,
                DirToByte(tr.plane.normal),
            );
            (*ent).s.otherEntityNum = (*other).s.number;
        } else if (tr.surfaceFlags & SURF_METALSTEPS) != 0 {
            G_AddEvent(
                &mut *(ent),
                EV_MISSILE_MISS_METAL as c_int,
                DirToByte(tr.plane.normal),
            );
        } else if (*ent).s.weapon != G2_MODEL_PART && isKnockedSaber == 0 {
            G_AddEvent(
                &mut *(ent),
                EV_MISSILE_MISS as c_int,
                DirToByte(tr.plane.normal),
            );
        }

        if isKnockedSaber == 0 {
            (*ent).freeAfterEvent = qtrue;
            (*ent).s.eType = ET_GENERAL as c_int;
        }

        tr.endpos = crate::g_weapon::SnapVectorTowards(tr.endpos, (*ent).s.pos.trBase);
        G_SetOrigin(&mut *(ent), tr.endpos);

        (*ent).takedamage = qfalse;
        // Splash damage
        if (*ent).splashDamage != 0 {
            if G_RadiusDamage(
                ctx,
                tr.endpos,
                ctx.entity_id_of(ent_resolve_opt(ctx, (*ent).parent)),
                (*ent).splashDamage as f32,
                (*ent).splashRadius as f32,
                ctx.entity_id_of(other),
                ctx.entity_id_of(ent),
                (*ent).splashMethodOfDeath,
            ) != 0
            {
                if hitClient == 0
                    && !(*ctx.world).g_entities[(*ent).r.ownerNum as usize]
                        .client
                        .is_null()
                {
                    (*((*ctx.world).g_entities[(*ent).r.ownerNum as usize].client
                        as *mut gclient_t))
                        .accuracy_hits += 1;
                }
            }
        }

        if (*ent).s.weapon == G2_MODEL_PART {
            (*ent).freeAfterEvent = qfalse;
        }

        trap::LinkEntity(
            ctx.engine,
            mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
        );
    }
}

/// Raven `G_RunMissile`.
///
/// Source: `oracle/codemp/game/g_missile.c:808-1019`
pub fn G_RunMissile(ctx: GameContext<'_>, ent: EntityId) {
    // Stage-1 seam bridge (rule 6): see G_MissileImpact. The verified body stays
    // pointer-based; `ent` is re-derived and sibling shard calls are bridged to
    // handles. Full accessor conversion is deferred (see report).
    unsafe {
        // `ent_h` avoids shadowing the `ent_id()` seam fn used in this body.
        let ent_h = ent;
        let ent: *mut gentity_t = ctx.entity_mut(ent_h);
        let mut origin: vec3_t = [0.0; 3];
        let mut groundSpot: vec3_t = [0.0; 3];
        let mut tr: trace_t = std::mem::zeroed();
        let mut passent: c_int;
        let mut isKnockedSaber = qfalse;

        if (*ent).neverFree != 0
            && (*ent).s.weapon == WP_SABER
            && (((*ent).flags & FL_BOUNCE_HALF) != 0)
        {
            isKnockedSaber = qtrue;
            (*ent).s.pos.trType = TR_GRAVITY;
        }

        // Get current position
        crate::bg_misc::BG_EvaluateTrajectory(&(*ent).s.pos, (*ctx.world).level.time, &mut origin);

        // Determine entity to pass (not collide with)
        if let Some(target_id) = (*ent).target_ent {
            passent = (*ctx.world).g_entities[target_id.index()].s.number;
        } else if ((*ent).r.svFlags & SVF_OWNERNOTSHARED) != 0
            && (((*ent).s.eFlags & EF_JETPACK_ACTIVE) != 0)
        {
            // Vehicle missile that should be solid to owner
            passent = (*ent).s.number;
        } else {
            passent = (*ent).r.ownerNum as c_int;
        }

        // Trace from previous position to current position
        if (*ctx.world).cvars.d_projectileGhoul2Collision.integer != 0 {
            trap::G2Trace(
                ctx.engine,
                mp_abi::game::syscalls::G_G2TRACE::GG2TraceArgs::new(
                    &mut tr,
                    &(*ent).r.currentOrigin,
                    &(*ent).r.mins,
                    &(*ent).r.maxs,
                    &origin,
                    passent,
                    (*ent).clipmask,
                    G2TRFLAG_DOGHOULTRACE
                        | G2TRFLAG_GETSURFINDEX
                        | G2TRFLAG_THICK
                        | G2TRFLAG_HITCORPSES,
                    (*ctx.world).cvars.g_g2TraceLod.integer,
                ),
            );

            if tr.fraction != 1.0 && (tr.entityNum as usize) < ENTITYNUM_WORLD as usize {
                let g2Hit = &mut (*ctx.world).g_entities[tr.entityNum as usize];
                if (*g2Hit).inuse != 0 && !(*g2Hit).client.is_null() && !(*g2Hit).ghoul2.is_null() {
                    (*((*g2Hit).client as *mut gclient_t)).g2LastSurfaceHit =
                        tr.surfaceFlags as c_int;
                    (*((*g2Hit).client as *mut gclient_t)).g2LastSurfaceTime =
                        (*ctx.world).level.time;
                }
                if !(*g2Hit).ghoul2.is_null() {
                    tr.surfaceFlags = 0;
                }
            }
        } else {
            trap::Trace(
                ctx.engine,
                mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                    &mut tr,
                    &(*ent).r.currentOrigin,
                    &(*ent).r.mins,
                    &(*ent).r.maxs,
                    &origin,
                    passent,
                    (*ent).clipmask,
                ),
            );
        }

        if tr.startsolid != 0 || tr.allsolid != 0 {
            // Make sure tr.entityNum is set to the entity we're stuck in
            trap::Trace(
                ctx.engine,
                mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                    &mut tr,
                    &(*ent).r.currentOrigin,
                    &(*ent).r.mins,
                    &(*ent).r.maxs,
                    &(*ent).r.currentOrigin,
                    passent,
                    (*ent).clipmask,
                ),
            );
            tr.fraction = 0.0;
        } else {
            crate::q_math::_VectorCopy(tr.endpos, &mut (*ent).r.currentOrigin);
        }

        if (*ent).passThroughNum != 0 && tr.entityNum as u32 == ((*ent).passThroughNum - 1) as u32 {
            crate::q_math::_VectorCopy(origin, &mut (*ent).r.currentOrigin);
            trap::LinkEntity(
                ctx.engine,
                mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
            );
            // Fall through to passthrough label
        } else {
            trap::LinkEntity(
                ctx.engine,
                mp_abi::game::syscalls::G_LINKENTITY::GLinkentityArgs::new(ent),
            );

            if (*ent).s.weapon == G2_MODEL_PART && (*ent).bounceCount == 0 {
                let mut lowerOrg: vec3_t = [0.0; 3];
                let mut trG: trace_t = std::mem::zeroed();

                crate::q_math::_VectorCopy((*ent).r.currentOrigin, &mut lowerOrg);
                lowerOrg[2] -= 1.0;
                trap::Trace(
                    ctx.engine,
                    mp_abi::game::syscalls::G_TRACE::GTraceArgs::new(
                        &mut trG,
                        &(*ent).r.currentOrigin,
                        &(*ent).r.mins,
                        &(*ent).r.maxs,
                        &lowerOrg,
                        passent,
                        (*ent).clipmask,
                    ),
                );

                crate::q_math::_VectorCopy(trG.endpos, &mut groundSpot);

                if trG.startsolid == 0
                    && trG.allsolid == 0
                    && trG.entityNum as u32 == ENTITYNUM_WORLD as u32
                {
                    (*ent).s.groundEntityNum = trG.entityNum as c_int;
                } else {
                    (*ent).s.groundEntityNum = ENTITYNUM_NONE as c_int;
                }
            }

            if tr.fraction != 1.0 {
                // Never explode or bounce on sky
                if (tr.surfaceFlags & SURF_NOIMPACT) != 0 {
                    // If grapple, reset owner
                    // PORT-NOTE(gclient_t): `client` is currently typed `*mut c_void`
                    // (gclient_t/MP not yet ported) — cast through per the field map
                    // ruling (gclient_t.hook is Option<EntityId>); see missing_symbols.
                    if let Some(parent_id) = (*ent).parent {
                        let parent_ptr = ent_resolve(ctx, parent_id);
                        if !(*parent_ptr).client.is_null() {
                            let client_ptr = (*parent_ptr).client as *mut gclient_t;
                            if (*client_ptr).hook == Some(ent_id(ent_base(ctx), ent)) {
                                (*client_ptr).hook = None;
                            }
                        }
                    }

                    if ((*ent).s.weapon == WP_SABER && (*ent).isSaberEntity != 0)
                        || isKnockedSaber != 0
                    {
                        G_RunThink(ctx, ctx.entity_id_of(ent).unwrap());
                        return;
                    } else if (*ent).s.weapon != G2_MODEL_PART {
                        G_FreeEntity(ctx, ctx.entity_id_of(ent));
                        return;
                    }
                }

                // Ghoul2 mark handling code is #if 0, so we skip to the active part
                if (*ent).s.weapon > WP_NONE as c_int
                    && (*ent).s.weapon < WP_NUM_WEAPONS as c_int
                    && ((tr.entityNum as usize) < MAX_CLIENTS
                        || (*ctx.world).g_entities[tr.entityNum as usize].s.eType
                            == ET_NPC as c_int)
                {
                    crate::q_math::_VectorCopy((*ent).r.currentOrigin, &mut (*ent).s.origin);
                    crate::bg_misc::BG_EvaluateTrajectory(
                        &(*ent).s.pos,
                        (*ctx.world).level.time,
                        &mut (*ent).s.origin2,
                    );

                    if VectorCompare((*ent).s.origin, (*ent).s.origin2) != 0 {
                        (*ent).s.origin2[2] += 2.0;
                    }
                }

                G_MissileImpact(ctx, ent_h, &mut tr);

                if tr.entityNum as u32 == (*ent).s.otherEntityNum as u32 {
                    (*ent).s.trickedentindex = 1;
                }

                if (*ent).s.eType != ET_MISSILE as c_int && (*ent).s.weapon != G2_MODEL_PART {
                    return; // Exploded
                }
            }
        }

        // passthrough label
        if (*ent).s.pos.trType == TR_STATIONARY && (((*ent).s.eFlags & EF_MISSILE_STICK) != 0) {
            // Stuck missiles should check some special stuff
            G_RunStuckMissile(ctx, ent_h);
            return;
        }

        if (*ent).s.weapon == G2_MODEL_PART {
            if (*ent).s.groundEntityNum == ENTITYNUM_WORLD as c_int {
                (*ent).s.pos.trType = TR_LINEAR;
                crate::q_math::VectorClear(&mut (*ent).s.pos.trDelta);
                (*ent).s.pos.trTime = (*ctx.world).level.time;

                crate::q_math::_VectorCopy(groundSpot, &mut (*ent).s.pos.trBase);
                crate::q_math::_VectorCopy(groundSpot, &mut (*ent).r.currentOrigin);

                if (*ent).s.apos.trType != TR_STATIONARY {
                    (*ent).s.apos.trType = TR_STATIONARY;
                    (*ent).s.apos.trTime = (*ctx.world).level.time;

                    (*ent).s.apos.trBase[ROLL as usize] = 0.0;
                    (*ent).s.apos.trBase[PITCH as usize] = 0.0;
                }
            }
        }

        // Check think function after bouncing
        G_RunThink(ctx, ctx.entity_id_of(ent).unwrap());
    }
}
